using Jindan.Contracts;
namespace Jindan.Modules.Board;

public sealed partial class BoardDocument
{
    string[] LinkedAssets() => Values.GetValueOrDefault("attachmentIds", "").Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries).Concat(Values.GetValueOrDefault("attachmentId", "").Split(',', StringSplitOptions.TrimEntries | StringSplitOptions.RemoveEmptyEntries)).Distinct().ToArray();
    public async Task AttachLocalFilesAsync(IEnumerable<string> paths, CancellationToken ct = default) { if (Context.ProjectId is null) throw new InvalidOperationException("첨부 자료를 보관할 프로젝트를 선택하세요."); var selected = paths.ToArray(); var ids = LinkedAssets().ToList(); if (selected.Length + ids.Count > 10) throw new InvalidOperationException("게시글 첨부는 최대10개입니다."); foreach (var source in selected) { var asset = await Services.Assets.ImportAsync(Services.Actor, Context.ProjectId, source, ct); if (!ids.Contains(asset.Id)) ids.Add(asset.Id); } SetField("attachmentId", ""); SetField("attachmentIds", string.Join(',', ids)); }
    async Task AttachDialogAsync() { using var dialog = new OpenFileDialog() { Multiselect = true, Title = "로컬 첨부 · 원본 보존 · 최대10개" }; if (dialog.ShowDialog(this) == DialogResult.OK) await AttachLocalFilesAsync(dialog.FileNames); }
    async Task SelectExistingAttachmentAsync() { var files = await Services.Data.ListAsync(Services.Actor, new("files")); using var dialog = new Form() { Text = "권한 있는 로컬 자료 연결", Width = 650, Height = 420, StartPosition = FormStartPosition.CenterParent }; var list = new CheckedListBox() { Dock = DockStyle.Fill, DisplayMember = "Name" }; foreach (var r in files) list.Items.Add(new AttachmentChoice(r.Fields.GetValueOrDefault("assetId", ""), r.Fields.GetValueOrDefault("title", r.Id))); var apply = new Button() { Text = "선택 자료 연결", Dock = DockStyle.Bottom, DialogResult = DialogResult.OK }; dialog.Controls.Add(list); dialog.Controls.Add(apply); if (dialog.ShowDialog(this) != DialogResult.OK) return; var ids = LinkedAssets().ToHashSet(); foreach (AttachmentChoice item in list.CheckedItems) { await Services.Assets.GetAsync(Services.Actor, item.Id); ids.Add(item.Id); } if (ids.Count > 10) throw new InvalidOperationException("첨부는 최대10개입니다."); SetField("attachmentId", ""); SetField("attachmentIds", string.Join(',', ids)); }
    sealed record AttachmentChoice(string Id, string Name);
    async Task DownloadAttachmentsAsync() { var ids = LinkedAssets(); if (ids.Length == 0) return; using var directory = new FolderBrowserDialog() { Description = "첨부의 새 복사본을 저장할 폴더" }; if (directory.ShowDialog(this) != DialogResult.OK) return; foreach (var id in ids) { var asset = await Services.Assets.GetAsync(Services.Actor, id); var target = Path.Combine(directory.SelectedPath, asset.OriginalName); if (File.Exists(target)) target = Path.Combine(directory.SelectedPath, Path.GetFileNameWithoutExtension(asset.OriginalName) + "-" + asset.Sha256[..8] + Path.GetExtension(asset.OriginalName)); await Services.Assets.ExportAsync(Services.Actor, id, target); } Notice.Text = "첨부 자료를 새 복사본으로 내보냈습니다."; }
}
